import { chromium } from 'playwright';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
const appUrl = pathToFileURL('/Users/raedmohammed/RaedWorkoutsV2/worktree-v16/index.html').href;
const user='ar-audit2';
const state={schema_version:2,programme_reference_migration_version:1,current_week:1,current_block:1,
 profile:{display_name:'اختبار',experience:'returning',created_at:'2026-08-25T00:00:00.000Z'},
 active_session:null,history:[],bodyweight_log:[],custom_videos:{},custom_jn_urls:{},video_hidden:{},
 custom_exercises:[],programme_overrides:null,prs:{},msg_index:0,substitutions:[]};
const settings={user_id:user,user_key:'',theme:'light',skin:'hadid',focus_mode:true,show_cues:true,
 rest_seconds:120,vibrate:false,notifications:false,music_platform:'none',block_auto_color:false,
 block_skin_suggestions:{},block_skin_rejections:{},lang:'ar',locale_version:1,runner_video_open:true};
const b=await chromium.launch({args:['--allow-file-access-from-files']});
const p=await b.newPage({viewport:{width:390,height:844}});
await p.route('https://**/*',r=>r.abort());
await p.addInitScript(({user,state,settings})=>{localStorage.clear();
 localStorage.setItem('raedworkouts.active_user',user);
 localStorage.setItem(`raedworkouts.${encodeURIComponent(user)}.state.v1`,JSON.stringify(state));
 localStorage.setItem(`raedworkouts.${encodeURIComponent(user)}.settings.v1`,JSON.stringify(settings));},{user,state,settings});
await p.goto(appUrl,{waitUntil:'domcontentloaded'});
await p.waitForTimeout(1000);
const visual = await p.evaluate((sel)=>{
  const el=document.querySelector(sel); if(!el) return '(missing)';
  const out=[]; const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT); let n;
  while((n=w.nextNode())){const s=n.textContent;
    for(let k=0;k<s.length;k++){ if(s[k]===' ')continue;
      const r=document.createRange(); r.setStart(n,k); r.setEnd(n,k+1);
      const bb=r.getBoundingClientRect(); out.push({c:s[k],x:bb.x,y:Math.round(bb.y/5)});}}
  out.sort((a,c)=> a.y-c.y || a.x-c.x);
  return 'SOURCE: '+el.textContent+'\nVISUAL: '+out.map(o=>o.c).join('');
},'.tb-meta');
console.log(visual);
const meta = await p.evaluate(()=>{
  const el=document.querySelector('#page-home .plan-row .meta'); if(!el) return '(missing)';
  const out=[]; const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT); let n;
  while((n=w.nextNode())){const s=n.textContent;
    for(let k=0;k<s.length;k++){ if(s[k]===' ')continue;
      const r=document.createRange(); r.setStart(n,k); r.setEnd(n,k+1);
      const bb=r.getBoundingClientRect(); out.push({c:s[k],x:bb.x,y:Math.round(bb.y/5)});}}
  out.sort((a,c)=> a.y-c.y || a.x-c.x);
  return 'SOURCE: '+el.textContent+'\nVISUAL: '+out.map(o=>o.c).join('')+'\nHTML: '+el.outerHTML;
});
console.log(meta);
await b.close();
